/**
 * ChatInterface.jsx
 * Main modern chat interface component
 * Integrates with Nova AI backend and all widgets
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import ChatMessage, { TypingIndicator } from './ChatMessage';
import { commandParser } from '../../services/CommandParser';
import { voiceSynthesis } from '../../services/VoiceSynthesis';
import './ChatStyles.css';

const ChatInterface = ({
  isOpen = true,
  isMinimized = false,
  onToggle = () => { },
  onMinimize = () => { },
  onWidgetCommand = () => { }
}) => {
  const [messages, setMessages] = useState([
    {
      id: 'welcome',
      text: "👋 Welcome to Nova AI! I'm your intelligent assistant. Ask me anything - search the web, get news, calculate numbers, or control your widgets.",
      isUser: false,
      timestamp: new Date(),
      isWelcome: true
    }
  ]);

  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);
  const [isOnline, setIsOnline] = useState(false);
  const [sessionId] = useState(() => `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`);

  // Get API configuration
  const getApiConfig = useCallback(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const apiPort = urlParams.get('api_port') || '5001';
    const apiHost = window.location.hostname || '127.0.0.1';
    return {
      baseUrl: `http://${apiHost}:${apiPort}`,
      chatEndpoint: '/api/chat',
      healthEndpoint: '/api/status'
    };
  }, []);

  // Check connection status
  const checkConnection = useCallback(async () => {
    try {
      const apiConfig = getApiConfig();
      const response = await fetch(`${apiConfig.baseUrl}${apiConfig.healthEndpoint}`, {
        method: 'GET',
        headers: { 'Cache-Control': 'no-cache' }
      });
      setIsOnline(response.ok);
    } catch (error) {
      setIsOnline(false);
    }
  }, [getApiConfig]);

  // Poll connection status
  useEffect(() => {
    checkConnection();
    const interval = setInterval(checkConnection, 30000); // Check every 30s
    return () => clearInterval(interval);
  }, [checkConnection]);

  // Auto-scroll to latest message
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  /**
   * Handle sending a message
   */
  const handleSendMessage = useCallback(async (e) => {
    e.preventDefault();

    const message = inputValue.trim();
    if (!message) return;

    // Add user message to chat
    const userMessage = {
      id: `msg-${Date.now()}`,
      text: message,
      isUser: true,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');

    // Parse the command
    const command = commandParser.parse(message);
    console.log('📝 Command parsed:', command);

    // Handle different command types
    if (command.type === 'clear') {
      handleClearCommand(command);
      return;
    }

    if (command.type === 'reset') {
      handleResetCommand();
      return;
    }

    // For widget commands, notify parent component
    if (commandParser.shouldGoToWidget(command)) {
      onWidgetCommand(command);
      addSystemMessage(`🎯 Routing to ${commandParser.getWidgetDisplayName(command.type)}`);
      return;
    }

    // For regular chat messages, get AI response from Nova AI backend
    setIsTyping(true);
    try {
      const apiConfig = getApiConfig();
      const response = await fetch(`${apiConfig.baseUrl}${apiConfig.chatEndpoint}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Cache-Control': 'no-cache'
        },
        body: JSON.stringify({
          message: message,
          session_id: sessionId,
          user_location: null
        })
      });

      if (!response.ok) {
        throw new Error(`API Error: ${response.status}`);
      }

      const data = await response.json();
      let novaResponse = data.response || 'I apologize, but I couldn\'t process that request.';

      // Check for special response markers
      if (novaResponse.includes('SEARCH_RESULT:')) {
        novaResponse = novaResponse.replace('SEARCH_RESULT:', '').trim();
        onWidgetCommand({ type: 'search' });
      }

      if (novaResponse.includes('WEATHER_DATA:')) {
        novaResponse = novaResponse.replace('WEATHER_DATA:', '').trim();
        onWidgetCommand({ type: 'weather' });
      }

      if (novaResponse.includes('NEWS_SUMMARY:')) {
        novaResponse = novaResponse.replace('NEWS_SUMMARY:', '').trim();
        onWidgetCommand({ type: 'news' });
      }

      // Add AI response
      addMessage(novaResponse, false);

      // Optionally speak the response
      if (shouldAutoSpeak()) {
        await voiceSynthesis.speak(novaResponse, {
          onStart: () => console.log('🔊 Speaking...'),
          onEnd: () => console.log('🔊 Done speaking')
        });
      }
    } catch (error) {
      console.error('Chat error:', error);
      addMessage(`I'm having trouble connecting to my systems right now. Please make sure the Nova AI server is running on the correct port. Error: ${error.message}`, false);
    } finally {
      setIsTyping(false);
    }
  }, [inputValue, onWidgetCommand, sessionId, getApiConfig]);

  /**
   * Add a regular message to chat
   */
  const addMessage = (text, isUser = false) => {
    const newMessage = {
      id: `msg-${Date.now()}`,
      text,
      isUser,
      timestamp: new Date()
    };
    setMessages(prev => [...prev, newMessage]);
  };

  /**
   * Add a system message (for status updates)
   */
  const addSystemMessage = (text) => {
    const newMessage = {
      id: `sys-${Date.now()}`,
      text,
      isUser: false,
      timestamp: new Date(),
      isSystem: true
    };
    setMessages(prev => [...prev, newMessage]);
  };

  /**
   * Handle clear widget commands
   */
  const handleClearCommand = (command) => {
    const widgetName = command.widget;
    addSystemMessage(`✅ ${widgetName ? `${widgetName} cleared` : 'Command executed'}`);

    onWidgetCommand({
      type: 'clear',
      widget: widgetName
    });
  };

  /**
   * Handle reset widgets command
   */
  const handleResetCommand = () => {
    addSystemMessage('🔄 All widgets reset to default positions and sizes');

    onWidgetCommand({
      type: 'reset'
    });
  };

  /**
   * Check if auto-speak is enabled
   */
  const shouldAutoSpeak = () => {
    return localStorage.getItem('chatAutoSpeak') === 'true';
  };

  /**
   * Handle voice input
   */
  const startVoiceInput = () => {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      addSystemMessage('⚠️ Voice input not supported in your browser');
      return;
    }

    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();

    recognition.onstart = () => {
      setIsListening(true);
    };

    recognition.onresult = (event) => {
      let transcript = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        transcript += event.results[i][0].transcript;
      }
      setInputValue(transcript);
    };

    recognition.onerror = (event) => {
      console.error('Speech recognition error:', event.error);
      addSystemMessage(`⚠️ Voice input error: ${event.error}`);
    };

    recognition.onend = () => {
      setIsListening(false);
    };

    recognition.start();
  };

  /**
   * Clear chat history
   */
  const clearHistory = () => {
    setMessages([
      {
        id: 'welcome',
        text: "👋 Welcome to Nova AI! I'm your intelligent assistant. Ask me anything - search the web, get news, calculate numbers, or control your widgets.",
        isUser: false,
        timestamp: new Date(),
        isWelcome: true
      }
    ]);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage(e);
    }
  };

  if (!isOpen) return null;

  return (
    <div className={`modern-chat-interface ${isOpen ? 'active' : ''} ${isMinimized ? 'minimized' : ''}`}>
      {/* Chat Header */}
      <div className="chat-header">
        <div className="chat-header-left">
          <div className="nova-avatar">
            <div style={{
              width: '40px',
              height: '40px',
              borderRadius: '50%',
              background: 'linear-gradient(135deg, rgba(0, 255, 136, 0.4), rgba(0, 200, 136, 0.6))',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '20px',
              color: '#00ff88'
            }}>
              ✨
            </div>
          </div>
          <div className="chat-header-info">
            <div className="chat-title">Nova AI Chat</div>
            <div className="chat-status">
              <div
                className={`status-dot ${isOnline ? 'online' : 'offline'}`}
                style={{
                  backgroundColor: isOnline ? '#00ff88' : '#ff4444',
                  boxShadow: isOnline ? '0 0 10px #00ff88' : 'none',
                  animation: isOnline ? 'statusPulse 2s ease-in-out infinite' : 'none'
                }}
              ></div>
              <span style={{ color: isOnline ? 'rgba(255, 255, 255, 0.8)' : '#ff4444' }}>
                {isOnline ? 'Online' : 'Offline'}
              </span>
            </div>
          </div>
        </div>

        <div className="chat-header-controls">
          <button
            className="chat-control-btn"
            onClick={clearHistory}
            title="Clear History"
            style={{
              background: 'none',
              border: 'none',
              color: '#00ff88',
              cursor: 'pointer',
              fontSize: '16px',
              padding: '8px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}
          >
            🗑️
          </button>

          <button
            className="chat-minimize-btn"
            onClick={onMinimize}
            title="Minimize"
            style={{
              background: 'none',
              border: 'none',
              color: '#00ff88',
              cursor: 'pointer',
              fontSize: '16px',
              padding: '8px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}
          >
            ➖
          </button>

          <button
            className="chat-close-btn"
            onClick={onToggle}
            title="Close"
            style={{
              background: 'none',
              border: 'none',
              color: '#00ff88',
              cursor: 'pointer',
              fontSize: '16px',
              padding: '8px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}
          >
            ✕
          </button>
        </div>
      </div>

      {/* Chat Messages Area */}
      {!isMinimized && (
        <>
          <div className="modern-chat-messages">
            {messages.map((msg) => (
              msg.isSystem ? (
                <div
                  key={msg.id}
                  style={{
                    textAlign: 'center',
                    color: 'rgba(255, 255, 255, 0.6)',
                    padding: '12px',
                    fontSize: '12px',
                    fontStyle: 'italic'
                  }}
                >
                  {msg.text}
                </div>
              ) : (
                <ChatMessage key={msg.id} message={msg} isUser={msg.isUser} />
              )
            ))}
            {isTyping && <TypingIndicator />}
            <div ref={messagesEndRef} />
          </div>

          {/* Chat Input Area */}
          <div className="modern-chat-input-area">
            <form onSubmit={handleSendMessage} className="chat-input-container">
              <div className="input-wrapper">
                <input
                  ref={inputRef}
                  type="text"
                  className="modern-chat-input"
                  placeholder="Type your message... (Shift+Enter for new line)"
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  onKeyDown={handleKeyDown}
                  maxLength={500}
                />

                <button
                  type="button"
                  className="chat-input-btn voice-btn"
                  onClick={startVoiceInput}
                  disabled={isListening}
                  title="Voice input"
                  style={{
                    background: isListening ? 'rgba(255, 0, 0, 0.3)' : 'transparent',
                    border: 'none',
                    color: isListening ? '#ff0000' : '#00ff88',
                    cursor: isListening ? 'not-allowed' : 'pointer',
                    fontSize: '16px',
                    padding: '8px',
                    marginRight: '8px'
                  }}
                >
                  🎤
                </button>

                <button
                  type="submit"
                  className="modern-send-button"
                  disabled={!inputValue.trim() || isTyping}
                  style={{
                    background: inputValue.trim() && !isTyping
                      ? 'linear-gradient(135deg, rgba(0, 255, 136, 0.6), rgba(0, 200, 136, 0.8))'
                      : 'rgba(0, 255, 136, 0.2)',
                    border: 'none',
                    color: '#00ff88',
                    cursor: inputValue.trim() && !isTyping ? 'pointer' : 'not-allowed',
                    padding: '10px 16px',
                    borderRadius: '6px',
                    fontSize: '16px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px'
                  }}
                >
                  <span>📤</span>
                </button>
              </div>

              <div style={{
                fontSize: '11px',
                color: 'rgba(255, 255, 255, 0.5)',
                marginTop: '6px'
              }}>
                {inputValue.length}/500
              </div>
            </form>
          </div>
        </>
      )}
    </div>
  );
};

export default ChatInterface;
